import "dotenv/config";
import type { PrismaConfig } from "prisma/config";

// Prisma 7 refuses a `url` in the schema's datasource block, so the migration
// CLI takes the connection from here — which makes this file a runtime
// requirement wherever `migrate deploy` runs (see the Dockerfile).
//
// `PrismaConfig` is imported as a TYPE only, and `defineConfig` is deliberately
// not used: a value import would make the runtime image need the `prisma`
// package resolvable next to this file, on top of the CLI itself. A plain
// object satisfying the same type keeps the config self-contained, and the
// `satisfies` clause keeps the shape checked.
export default {
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: process.env["DATABASE_URL"],
  },
} satisfies PrismaConfig;
